<?php declare(strict_types=1);require_once __DIR__.'/auth.php';$u=portal_require();$q=$db->prepare('SELECT client_id FROM client_portal_users WHERE id=?');$q->execute([$u['id']]);$client=(int)$q->fetchColumn();$rows=[];$tables=$db->query("SHOW TABLES LIKE 'invoices'")->fetchColumn();if($tables){$q=$db->prepare('SELECT * FROM invoices WHERE client_id=? ORDER BY created_at DESC');$q->execute([$client]);$rows=$q->fetchAll();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoices</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4"><a href="index.php">← Dashboard</a><h1 class="h3 mt-3">Invoices</h1><?php if(!$tables):?><div class="alert alert-warning">Invoice module is not available yet.</div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><?php foreach(array_keys($rows[0]??['id'=>'','status'=>'','total'=>'']) as $k):?><th><?=htmlspecialchars($k)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=htmlspecialchars((string)($v??''))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></main></body></html>